sql:
SELECT COUNT(order_id) AS canceled_orders
FROM orders
WHERE order_status = 'canceled';

SELECT AVG(order_items.price + order_items.freight_value) AS average_order_value
FROM orders
JOIN order_items ON orders.order_id = order_items.order_id;

SELECT SUM(payment_value) AS total_paid_by_credit_card
FROM order_payments
WHERE payment_type = 'credit_card';

SELECT COUNT(product_id) AS products_without_category
FROM products
WHERE product_category_name IS NULL;

SELECT COUNT(order_id) AS canceled_orders
FROM orders
WHERE order_status = 'canceled';

SELECT SUM(payment_value) AS total_paid_by_credit_card
FROM order_payments
WHERE payment_type = 'credit_card';

SELECT COUNT(*) AS products_without_category
FROM products
WHERE product_category_name IS NULL;

SELECT AVG(items_per_order) AS avg_items_per_order
FROM (
    SELECT COUNT(*) AS items_per_order
    FROM order_items
    GROUP BY order_id
) AS subquery;
